package dev.zomboid.tacz;
/** Restore the cursor entity at the instant of vanilla attack; never sends extra attacks. */
public final class BareHand {
 public static void prepare(){try{Object mc=Bridge.mc(),player=R.get(mc,"player");if(!Bridge.isoActive()||player==null||R.get(mc,"screen")!=null||!R.yes(R.call(R.call(player,"getMainHandItem"),"isEmpty")))return;Object hit=R.get(R.type("com.cleannrooster.dungeons_iso.mod.Mod"),"crosshairTarget");if(hit==null||!R.call(hit,"getType").toString().equals("ENTITY"))return;Object entity=R.call(hit,"getEntity");if(!R.yes(R.call(entity,"isAlive"))||!R.yes(R.call(player,"canInteractWithEntity",entity,0d)))return;Object eye=R.call(player,"getEyePosition"),head=R.call(entity,"getEyePosition"),center=R.call(R.call(entity,"getBoundingBox"),"getCenter"),level=R.get(mc,"level");if(!visible(level,player,eye,head)&&!visible(level,player,eye,center))return;Object restored=R.make("net.minecraft.world.phys.EntityHitResult",entity,center);R.set(mc,"hitResult",restored);R.set(mc,"crosshairPickEntity",entity);}catch(Throwable e){Bridge.warn("bare hand cursor targeting",e);}}
 static boolean visible(Object level,Object player,Object eye,Object point){Object hit=Bridge.clip(level,player,eye,point);return !R.call(hit,"getType").toString().equals("BLOCK")||Bridge.distance(eye,R.call(hit,"getLocation"))>=Bridge.distance(eye,point)-.05;}
}
